view.template:
{% load view_tags %}
{% get_values 'project/research_field' as research_fields %}
{% get_set 'project/partner/id' as partners %}
{% get_value 'project/title' as title %}
{% get_value 'project/schedule/project_end' as release_date %}
{% get_values 'smp/software-pid' as software_pids %}
{% get_values 'smp/software-license' as software_licenses %}
{% get_values 'smp/language' as programming_languages %}
<pre>
{
    "@context": "https://w3id.org/codemeta/3.0",
    "name": "{{ title.value }}",
    "@type": "SoftwareSourceCode"{% if research_fields|length == 1 %},    
    "applicationCategory": "{{ research_fields.0.value }}"{% elif research_fields|length > 1 %},
    "applicationCategory": [
        {% for rf in research_fields %}"{{ rf.value }}"{% if not forloop.last %},
        {% endif %}{% endfor %}
    ]{% endif %}{% if partners|length %},
    "contributor": [{% for p in partners %} {% with p_set_index_str=p.set_index|stringformat:"s" %} {% get_set_value p 'project/partner/type' as p_type %} {% get_set_value p 'project/partner/family-name' as p_family_name %} {% get_set_value p 'project/partner/given-name' as p_given_name %} {% get_set_value p 'project/partner/name' as p_name %} {% get_set_value p 'project/partner/orcid' as p_orcid %} {% get_set_value p 'project/partner/website' as p_website %} {% get_values 'project/partner/affiliation' p_set_index_str as p_affiliations %} {% get_values 'project/partner/affiliation/ror-id' p_set_index_str as p_ror_ids %} {% get_values 'project/partner/role' p_set_index_str as p_roles %}
        {% if p_type.option_uri == 'https://rdmo.mpdl.mpg.de/terms/options/partner-types/person' %}{
            {% if p_orcid.value %}"@id": "{{ p_orcid.value }}",
            {% endif %}"@type": "Person",
            "familyName": "{{ p_family_name.value }}",
            "givenName": "{{ p_given_name.value }}"{% elif p_type.option_uri == 'https://rdmo.mpdl.mpg.de/terms/options/partner-types/entity' %}{
            {% if p_website.value %}"@id": "{{ p_website.value }}",
            {% endif %}"@type": "Organization",
            "name": "{{ p_name.value }}"{% endif %}{% if p_affiliations|length and p_affiliations|length == 1 and p_affiliations.0.value %},
            "affiliation": {
                {% if p_ror_ids|length and p_ror_ids.0.value %}"@id": "{{ p_ror_ids.0.value }}",
                {% else %}{% endif %}"@type": "Organization",
                "name": "{{ p_affiliations.0.value }}"
            }{% elif p_affiliations|length and p_affiliations|length > 1 %},
            "affiliation": [
                {% for p_affiliation in p_affiliations %}{% if not forloop.first %}    {% endif %}{% if p_affiliation.value %}{ {% if p_ror_ids|length %}{% for p_ror_id in p_ror_ids %}{% if p_ror_id.set_index == p_affiliation.set_index and p_ror_id.value %}
                    "@id": "{{ p_ror_id.value }}",{% endif %}{% endfor %}
                    {% else %}
                    {% endif %}"@type": "Organization",
                    "name": "{{ p_affiliation.value }}"
                }{% if not forloop.last %}, {% endif %}{% endif %}
            {% endfor %}]{% endif %}
        {% if p_type.option_uri %}}{% endif %}{% if p_orcid.value or p_website.value %}{%if p_roles|length %},
        {% for p_role in p_roles %}{% if p_role.value %}{
            "@type": "Role",
            "contributor": "{% if p_orcid.value %}{{ p_orcid.value }}{% elif p_website.value %}{{ p_website.value }}{% endif %}",
            "roleName": "{{ p_role.value }}"
        }{% if not forloop.last %}, 
        {% endif %}{% endif %}{% endfor %}{% endif %}{% endif %}{% if not forloop.last %}{% if p_type.option_uri %},{% endif %}{% endif %}{% endwith %}{% endfor %}
    ]{% endif %}{% if software_licenses|length == 1 %},
    "license": {% if software_licenses.0.text %}"{{ software_licenses.0.text }}"{% else %}"https://spdx.org/licenses/{{ software_licenses.0.option_text }}"{% endif %}{% elif software_licenses|length > 1 %},
    "license": [
        {% for sl in software_licenses %}{% if sl.text %}"{{ sl.text }}"{% else %}"https://spdx.org/licenses/{{ sl.option_text }}"{% endif %}{% if not forloop.last %},
        {% endif %}{% endfor %}
    ]{% endif %}{% if software_pids|length == 1 %},
    "identifier": {
        "@type": "PropertyValue",
        "propertyID": "{{ software_pids.0.option_text|lower }}",
        "value":  "{{ software_pids.0.text }}"
    }{% elif software_pids|length > 1 %},
    "identifier": [{% for sp in software_pids %}
        {
            "@type": "PropertyValue",
            "propertyID": "{{ sp.option_text|lower }}",
            "value":  "{{ sp.text }}"
        }{% if not forloop.last %}, {% endif %}{% endfor %}
    ]{% endif %}{% if release_date.value %},
    "datePublished": "{{ release_date.value|date:"Y-m-d" }}"{% endif %}{% if programming_languages|length == 1 %},
    "programmingLanguage": "{{ programming_languages.0.value }}"{% elif programming_languages|length > 1 %},
    "programmingLanguage": [
        {% for pl in programming_languages %}{% if not forloop.first %}    {% endif %}"{{ pl.value }}"{% if not forloop.last %},{% endif %}
    {% endfor %}]{% endif %}
}
</pre>
